package org.apache.commons.math3.optimization.direct;

import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.optimization.direct.CMAESOptimizer;
import org.junit.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

public class AgentBRT_Math_19_raw_diff_Test {

    @Test(expected = NumberIsTooLargeException.class)
    public void testReproduceBug() throws Exception {
        // Create an instance of CMAESOptimizer with default parameters
        CMAESOptimizer optimizer = new CMAESOptimizer();

        // Use reflection to set the private boundaries field
        Field boundariesField = CMAESOptimizer.class.getDeclaredField("boundaries");
        boundariesField.setAccessible(true);

        // Set up the bounds to trigger the overflow condition
        double[][] boundaries = {
            {Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY},
            {Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY}
        };
        boundariesField.set(optimizer, boundaries);

        // Use reflection to access the private checkParameters method
        Method checkParametersMethod = CMAESOptimizer.class.getDeclaredMethod("checkParameters");
        checkParametersMethod.setAccessible(true);

        // Invoke the method that should trigger the bug
        checkParametersMethod.invoke(optimizer);
    }
}

